using System.Collections.Generic;

namespace Vlab.Product
{
    // Learner-visible interpretation from the experiment brief and the supplied kit contracts.
    public static class LessonContext
    {
        static readonly Dictionary<string,string[]> notes=new Dictionary<string,string[]>
        {
            ["P01"]=new[]{"Chiều dài đo từ điểm treo tới tâm quả. Đồng hồ đếm các lần qua mốc cùng chiều. Mô hình không có lực cản; góc lớn làm chu kỳ tăng. Mỗi lượt được ghi riêng, không đồng nghĩa đã làm đủ cả chuỗi so sánh.","Length is pivot to bob centre. Timing uses crossings in the same direction. The model omits drag and retains large-angle period changes. A saved trial is separate from completion of the full comparison series."},
            ["P02"]=new[]{"Chân bộ phóng giữ nguyên. Độ cao là chênh giữa nòng thực và thảm hứng, thay đổi theo góc; đây không phải loạt bắn h₀=0. Vì vậy không kết luận hai góc bù có tầm xa bằng nhau. Chỉ dùng lần chạm đầu, bỏ qua lực cản.","The launcher keeps its native seated base. Actual muzzle-to-mat height varies with angle; this is not an equal-height h₀=0 series, so complementary-angle ranges need not match. First impact only; air drag omitted."},
            ["P03"]=new[]{"Ngưỡng nghỉ và lực trượt lấy từ quá trình kéo. Hệ số ma sát là điều kiện mô phỏng đã khai báo, không phải phép hiệu chuẩn vật liệu thật.","Breakaway and sliding readings come from the pull process. Friction coefficients are declared simulation conditions, not measured material calibration."},
            ["P04"]=new[]{"Bản chắn thật rộng 50 mm. Tốc độ d/Δt là trung bình trong lúc chắn cổng; không xem đó là vận tốc tức thời chính xác khi xe đang tăng tốc.","The supplied flag is 50 mm wide. d/Δt is an average during gate blocking, not an exact instantaneous speed under acceleration."},
            ["P05"]=new[]{"Lò xo có chiều dài tự nhiên 150 mm, hành trình được bộ mẫu hỗ trợ 100–200 mm. Chọn tải và biên độ trong giới hạn này. Mô hình đàn hồi tuyến tính, bỏ qua khối lượng lò xo và lực cản.","The source spring has 150 mm rest length and 100–200 mm supported travel. Load and amplitude must fit this range. Linear elasticity; spring mass and damping omitted."},
            ["P06"]=new[]{"Động lượng có dấu theo chiều dương đã chọn. Mẫu mô phỏng va chạm đàn hồi lý tưởng hoặc dính hoàn toàn; không suy ra hệ số đàn hồi của vật liệu thật.","Momentum is signed in the chosen positive direction. Collisions are ideal elastic or fully sticking; no real material restitution is inferred."},
            ["P07"]=new[]{"Phân biệt gia tốc từ cổng quang với giá trị dự đoán từ mô hình. Với loạt đổi lực, giữ tổng khối lượng xe và tải treo không đổi; với loạt đổi khối lượng, giữ tải treo không đổi. Dây và ròng rọc được coi là lý tưởng.","Distinguish photogate acceleration from the model prediction. Force series hold cart plus hanger mass fixed; mass series hold the hanger fixed. String and pulley are idealised."},
            ["P08"]=new[]{"Thí nghiệm dùng xe trượt, bỏ qua năng lượng quay của bánh. Số đo d/Δt thuộc vùng cổng. Nếu vật không tự trượt, ghi nhận trạng thái đó thay vì tạo số đo qua cổng.","The glider model omits wheel rotational energy. d/Δt belongs to the gate interval. A stalled trial records that observation rather than inventing a gate passage."},
            ["C01"]=new[]{"Pipette đúng 10 mL; burette 25 mL, lưu lượng mở hết 0,5 mL/s. Cần ba titre hợp lệ gần nhau trong 0,10 mL và màu hồng nhạt bền sau trộn. Mẫu giấm đã pha loãng được mô hình hóa như acid acetic.","10 mL pipette; 25 mL burette; 0.5 mL/s at full opening. Three valid titres must agree within 0.10 mL, with persistent pale pink after mixing. The diluted vinegar is modelled as acetic acid."},
            ["C02"]=new[]{"Đọc điện áp khi cả điện cực và cầu muối tiếp xúc đúng dung dịch. Nồng độ thay cho hoạt độ trong phương trình Nernst. Đảo đầu đo đổi dấu, không đổi bản chất phản ứng.","Voltage requires both wet electrodes and the immersed salt bridge. Concentrations approximate activities in the Nernst model. Reversing probes changes sign, not the reaction."},
            ["C03"]=new[]{"Điện lượng được tích phân khi nguồn thực sự bật. Khối lượng sau phải là điện cực đã rửa và làm khô. Mô hình Faraday dùng hiệu suất dòng 100%; không mô phỏng đầy đủ phản ứng phụ.","Charge integrates only while the source is on. Final mass requires a rinsed, dry electrode. The Faraday model assumes 100% current efficiency and omits detailed side reactions."},
            ["C04"]=new[]{"Mỗi lần nhỏ là 2 đơn vị mô phỏng định tính, không phải 2 mL hay số mol. So sánh NaCl, NaNO₃ và nước; không suy ra nồng độ chloride từ lượng cặn.","Each deliberate dose is 2 qualitative simulation units, not 2 mL or moles. Compare NaCl, NaNO₃ and water; sediment does not determine chloride concentration."},
            ["C05"]=new[]{"Pipette chuyển 10 mL; chọn bình định mức thật 50 hoặc 100 mL. Thể tích cuối là thể tích dung dịch tới vạch, không phải lượng nước đã thêm. Mỗi mẫu nối tiếp giữ mã nguồn và lượng chất tan.","Transfer 10 mL into an actual 50 or 100 mL volumetric flask. Final volume is solution to the mark, not added water. Serial samples retain source identity and solute amount."},
            ["C06"]=new[]{"Giấy BTB chỉ phân biệt các khoảng pH ≤6, 6–7,6 và ≥7,6; không đọc pH chính xác từ màu. Đầu dò phải được hiệu chuẩn, rửa và ngập đúng. Dung dịch acid/base một nấc mạnh được xét ở 25 °C.","BTB gives intervals ≤6, 6–7.6 and ≥7.6, not an exact colour-derived pH. Calibrate, rinse and fully immerse the probe. The sample model is strong monoprotic acid/base at 25 °C."},
            ["C07"]=new[]{"Ba cỡ hạt có cùng khối lượng mỗi nhóm, diện tích tương đối 4/2/1. Động học là minh họa, không phải hằng số tốc độ thực nghiệm. Khí lý tưởng ở 298,15 K và 1 atm; không đọc vượt syringe 100 mL.","The three chip sizes have equal batch mass and relative areas 4/2/1. Kinetics are illustrative, not experimentally calibrated. Ideal gas at 298.15 K and 1 atm; syringe limit 100 mL."},
            ["C08"]=new[]{"Bộ nhiệt lượng kế dùng 57 000 J/mol, khối lượng riêng 1 g/mL và nhiệt dung riêng 4,18 J/g/K. Tính cả thể tích, nhiệt độ ban đầu hai dung dịch và nhiệt dung cốc. Đây là mô hình, không phải số liệu hiệu chuẩn thiết bị thật.","The source calorimeter uses 57000 J/mol, density 1 g/mL and specific heat 4.18 J/g/K. Both solution volumes/temperatures and cup heat capacity are included. These are model assumptions, not physical calibration."},
            ["B01"]=new[]{"Tiêu bản là sơ đồ 64 tế bào, không phải ảnh hiển vi thật hay thước chuẩn quang học. Vật kính 4×/10×/40× và thao tác lấy nét là minh họa. Tự gọi tên cấu trúc đang quan sát.","The specimen is a 64-cell schematic, not a micrograph or optical calibration. The 4×/10×/40× objectives and focus interaction are illustrative. Identify structures yourself."},
            ["B02"]=new[]{"Bốn hình minh họa trạng thái không phải dữ liệu động học hoặc đáp ứng định lượng theo nồng độ. Theo dõi cùng mã tế bào và tự đếm; thời gian phục hồi tính từ lúc thực sự thay nước. Không suy ra tốc độ sinh học từ chuyển hình.","The four state illustrations are not calibrated kinetics or concentration-response data. Track the same IDs and count them yourself. Recovery time starts at actual water replacement; image changes do not measure a biological rate."},
            ["B03"]=new[]{"Ba mã là ba mẫu độc lập; cân lại cùng một mẫu không tạo lần lặp độc lập. Đáp ứng thẩm thấu có nhiễu được mô phỏng, không phải hiệu chuẩn khoai thật. Giữ đồng nhất thời gian, kích thước và cách thấm mẫu.","Three IDs are independent samples; reweighing one sample is not another replicate. The seeded osmotic response is illustrative, not calibrated potato data. Hold time, size and blotting protocol fixed."},
            ["B04"]=new[]{"Bể nhiệt chứa aliquot trong cốc, rồi chuyển vào bình phản ứng. Sau trộn, mô hình cho mẫu nguội dần về 25 °C; nhiệt độ mẫu khác nhiệt độ bể. Sinh khí và bất hoạt nhiệt là minh họa, cần so với mẫu bất hoạt/nước.","A beaker aliquot equilibrates in the bath, then transfers into the reaction flask. After mixing the model cools toward 25 °C; sample and bath temperatures differ. Gas production/inactivation are illustrative; compare inactive/water controls."},
            ["B05"]=new[]{"Mô hình có thời gian trễ minh họa 15 giây và lượng đường hữu hạn. Mẫu không đường bỏ qua dự trữ nội sinh; mẫu bất hoạt khác mẫu không có nấm men. Khí CO₂ là giả thiết mô hình, không phải phép thử định danh khí.","The model has a 15 s illustrative lag and finite sugar. The no-sugar control omits endogenous reserves; inactive yeast differs from no yeast. CO₂ identity is assumed, not established by an assay."},
            ["B06"]=new[]{"Băng A/B và hệ dung môi là dữ liệu minh họa. Không gọi tên sắc tố chỉ từ màu hay Rf. Đánh dấu mặt trước từ cùng vạch gốc; chấm khô từng lần và không để vạch mẫu ngập dung môi.","Bands A/B and solvent systems are illustrative. Colour or Rf alone does not identify a pigment. Measure front and bands from the same origin; dry each spot and keep the origin above solvent."},
            ["B07"]=new[]{"Vật liệu trắng là kết tủa thô, có thể gồm DNA và tạp chất. Không suy ra độ tinh sạch, khối lượng hay sợi xoắn phân tử. Nhiệt độ alcohol là điều kiện ghi lại; mô hình hiện chưa định lượng ảnh hưởng của nó.","White material is crude precipitate that may include DNA and contaminants. No purity, mass or molecular helix is inferred. Alcohol temperature is a recorded condition; its quantitative effect is not modelled."},
            ["B08"]=new[]{"Atlas 100 mã là sơ đồ giải thích, không phải mẫu tần suất pha ngoài tự nhiên. Tự phân loại, giữ nhóm Chưa rõ, không đếm trùng khi đổi nửa ảnh. MI được tính từ đáp án đã ghi của người học.","The 100-ID atlas is an explanatory schematic, not a natural phase-frequency sample. Classify manually, retain unclear cells and deduplicate overlapping crops. MI comes from the learner's recorded answers."},
            ["M01"]=new[]{"Bộ răng thật gồm 12–24–36 răng, module 2 mm. Bánh trung gian đổi quan hệ chiều quay; phải giữ đúng đầu vào/đầu ra đang chọn. Không suy ra hiệu suất hay mômen từ hình học lý tưởng.","The supplied train has 12/24/36 teeth, module 2 mm. An idler changes the direction relationship; retain the chosen input/output identities. Ideal geometry does not establish efficiency or torque."},
            ["M02"]=new[]{"Tính mômen quanh đúng lỗ điểm tựa. Mô hình này có trọng lượng thanh khai báo 0,5 N và phản lực đỡ; không phải thanh không khối lượng khi điểm tựa lệch tâm.","Take moments about the actual pivot bore. This model includes a declared 0.5 N beam weight and support reaction; it is not a massless lever at an off-centre pivot."},
            ["M03"]=new[]{"Chỉ dùng sơ đồ 1, 2 hoặc 4 nhánh chịu tải. Độ kéo dây và độ nâng tải phải khớp nhau. Tổng tải đã khai báo gồm phần chuyển động; hiệu suất là giả thiết, không phải lực ma sát được đo.","Use the explicit 1/2/4 supporting-strand routes. Rope pull and load rise must agree. Declared load includes moving parts; efficiency is prescribed, not measured friction."},
            ["M04"]=new[]{"Pulley đúng 40/80 mm và các đai có chiều dài cố định; đổi khoảng tâm là đổi bộ đai, không kéo giãn. Trượt là tham số áp đặt ở trục ra, không phải lực căng hay độ đàn hồi đã được đo.","The 40/80 mm pulleys use fixed-length belts; a different centre distance selects another belt, not a stretched loop. Output slip is prescribed; tension and elasticity are not measured."},
            ["M05"]=new[]{"Chọn tay quay 20/30/40 mm và thanh truyền 80/100/120 mm thật. Đây là quan hệ động học lý tưởng; không suy ra lực khớp, ma sát hay độ bền.","Use the supplied 20/30/40 mm crank positions and 80/100/120 mm rods. This is ideal kinematics, not a joint-force, friction or strength model."},
            ["M06"]=new[]{"Cam được cung cấp có độ nâng 10 mm và góc nâng/hạ 120°. Con đội dao và con lăn là hai tiếp xúc khác nhau. Bộ hiện tại chưa có cam đổi độ nâng hay góc; không trình bày biến thể lý thuyết như phép đo trên cam này.","The supplied cam has 10 mm lift and 120° rise/return sectors. Knife and roller contacts differ. Variable-lift/sector cams are not supplied; theoretical alternatives are not measurements of this cam."},
            ["M07"]=new[]{"Chọn đúng mã mẫu và mặt đo. Sửa số đọc bằng sai lệch không đã ghi; thước kẹp 0,02 mm, panme 0,01 mm. Tiếp xúc và ratchet là tương tác ảo, không có cảm biến lực thật.","Keep sample identity and measuring faces fixed. Correct the reading by the recorded zero error; caliper resolution 0.02 mm, micrometer 0.01 mm. Contact/ratchet are virtual, without physical force sensing."},
            ["M08"]=new[]{"Dầm tựa hai đầu, tải giữa nhịp và môđun Young đã khai báo. Chỉ xét võng nhỏ δ/L≤0,01; bỏ qua trọng lượng bản thân, cắt và phá hủy. Cần tháo tải để kiểm tra số chỉ trở về.","Simply supported beam, central load and declared Young's modulus. Small deflection δ/L≤0.01; self-weight, shear and fracture omitted. Unload and verify the gauge returns."}
        };
        public static string Explanation(string id,bool vietnamese,ModelResult result=null)
        {
            string text=notes.TryGetValue(id,out var pair)?pair[vietnamese?0:1]:"";
            if(!vietnamese&&result!=null&&!string.IsNullOrEmpty(result.note)&&!text.Contains(result.note))text+="\n"+result.note;
            return text;
        }
    }
}
